preConditionHook:
// TAKE PROFIT AT THE OLD SWING POINT, BUT ONLY ONCE THE TRADE HAS PAID. Two
// readings of one exit: T18-23 takes profit ABOVE the most recent swing high
// once open profit is large enough, R30-06 takes it AT OR SLIGHTLY BELOW that
// high once the rally is judged to be maturing. One rule with a SIGNED
// offsetTicks -- +1 is T18-23, -3 is R30-06 -- and the dollar threshold stands
// in for "the trend has run far enough", R30-06's maturing-trend gate having
// no bar-level test in that chapter.
//
// THE CONJUNCTION IS WHY THIS IS ONE RULE. Exits are ORed by the pane, so a
// dollar target AND a price level cannot be composed from TakeProfit plus a
// level exit: ORed they would fire on whichever came first, which is the
// opposite of what Brooks says. TakeProfitWithRatioStop is the corpus's other
// exit written whole for the same reason.
//
// BOTH SOURCES DESCRIBE PARTIAL PROFIT TAKING, which the engine's
// whole-position Exit cannot express; carried as a full exit, per T18-23's own
// note.
//
// ctx.OpenPositionProfit() is VERIFIED as close-marked and NET of the entry
// side's commission, slippage and accrued swap -- one side, not the round turn
// -- so profitThreshold is a net-of-entry-costs dollar figure. The
// MarketPosition gate is required because the accessor reads 0 while flat and
// 0 >= 0 would fire a threshold of 0.
//
// maxBarsBack IS PROMOTED: the merged parameters give no pivot window, and the
// scan's Length is not optional. 60 matches the other swing-structure rules of
// this family.
//
// Ticks division-first, ctx.MinMove() / ctx.PriceScale() computed once into
// tickSz; both are per-symbol constants (VERIFIED, one change print per chart,
// at bar 1). The -1 sentinel is guarded: as a PRICE it sits under every real
// price, so an unguarded long would exit on its entry bar.
//
// PIVOT SCAN inlined from SwingHigh.json per the B-list decision. MEASURED
// (EL_Swing_Probe.txt, @ES 60 min): the pivot bar is AT OR ABOVE the `strength`
// OLDER bars and STRICTLY ABOVE the `strength` NEWER bars -- bars-ago indexing,
// so the newer bars are the smaller k and take el_gt / el_lt, the older el_ge /
// el_le; lag exactly `strength`; candidate offsets strength..maxBarsBack-1, the
// neighbourhood reaching `strength` bars past the window, so the deepest bar
// touched is maxBarsBack - 1 + strength. Newest-first with a break reproduces
// occurrence 1. The comparisons carry the 2.22e-12 relational tolerance.
//
// Not SwingPivotTarget, which exits at the pivot with NO profit gate and an ATR
// tolerance; this adds the dollar leg and offsets in ticks, signed, so it can
// sit just short of the level. Not TakeProfit, the dollar leg alone.
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration
// is a redefinition when this rule is placed twice in one strategy.
// Every one is fully assigned each bar before it is read.
tickSz = ctx.MinMove() / ctx.PriceScale();
pivS = (int)strength;
pivW = (int)maxBarsBack;
swHiPx = -1.0;
for (int j = pivS; j <= pivW - 1; ++j) {
    bool ok = true;
    for (int k = j - pivS; k < j; ++k) {
        if (!el_gt(high[j], high[k])) { ok = false; break; }
    }
    if (ok) {
        for (int k = j + 1; k <= j + pivS; ++k) {
            if (!el_ge(high[j], high[k])) { ok = false; break; }
        }
    }
    if (ok) { swHiPx = high[j]; break; }
}
swLoPx = -1.0;
for (int j = pivS; j <= pivW - 1; ++j) {
    bool ok = true;
    for (int k = j - pivS; k < j; ++k) {
        if (!el_lt(low[j], low[k])) { ok = false; break; }
    }
    if (ok) {
        for (int k = j + 1; k <= j + pivS; ++k) {
            if (!el_le(low[j], low[k])) { ok = false; break; }
        }
    }
    if (ok) { swLoPx = low[j]; break; }
}
haveHi = (swHiPx != -1.0);
haveLo = (swLoPx != -1.0);
